Shared setup
The hidden setup loads the shared F01 helpers and enables automatic chunk labels before any code is displayed.
Next we’ll identify the execution mode. The table below tells us whether this page is showing saved results or refreshing calculations from the fitted models. Model refitting takes place in F01; an ordinary render here reviews the current tables and figures.


Code
# rd04-parameters
# A refit also refreshes the results derived from the new models.
recompute &lt;- isTRUE(params$recompute) || isTRUE(params$refit)
output_root &lt;- "outputs"
data.frame(
  Mode = if (isTRUE(params$refit)) {
    "Refresh after F01 refit"
  } else if (recompute) {
    "Recompute from saved models"
  } else {
    "Review saved results"
  }
)


                  Mode
1 Review saved results

Generate the figure and canonical estimates
We can now turn the audited calculation into the 60 estimates for the inventory figure and table. This formatter applies the interval methods defined above to the mapped F01 models.


Code
# rd04-estimate-rows
summarize_integrated &lt;- function(
  s,
  component,
  model_id,
  phase = NULL,
  difference = FALSE
) {
  prediction &lt;- custom_integrated(s)
  # Means use log-delta intervals; signed differences use response-scale ones.
  low &lt;- if (difference) {
    prediction$estimate - qnorm(.975) * prediction$se
  } else {
    prediction$estimate *
      exp(-qnorm(.975) * prediction$se / prediction$estimate)
  }
  high &lt;- if (difference) {
    prediction$estimate + qnorm(.975) * prediction$se
  } else {
    prediction$estimate * exp(qnorm(.975) * prediction$se / prediction$estimate)
  }
  labels &lt;- s$avg$labels
  # Joint models carry phase labels in the grid; separate phase fits use the
  # registered phase. A signed contrast is labeled separately from load means.
  phase_values &lt;- if (difference) {
    rep("Vegetation difference", nrow(labels))
  } else {
    values &lt;- if ("phase" %in% names(labels)) {
      as.character(labels$phase)
    } else {
      rep(phase, nrow(labels))
    }
    stopifnot(all(values %in% c("prepct", "postpct")))
    ifelse(values == "prepct", "Pre-PCT", "Post-PCT")
  }
  tibble(
    component = component,
    phase = phase_values,
    treatment = as.character(labels$treatment),
    estimate = prediction$estimate,
    se = prediction$se,
    lcl = low,
    ucl = high,
    model_id = model_id,
    estimand = if (difference) {
      "integrated matched woody mean difference (pre-PCT minus post-PCT)"
    } else {
      "site-standardized random-effect-integrated expected load"
    },
    interval_method = if (difference) {
      "response-scale delta method with joint phase covariance"
    } else {
      "log-scale delta method for integrated mean"
    },
    random_intercept_variance = s$variance
  )
}


We’ll calculate the phase means and woody change from those fits and collect them in one source table for the publication. The table below shows every mean and interval behind the figure. Checks ensure all 60 cells are present and that woody change equals the difference between the displayed phase means.


Inspect all 60 full-precision estimates and their calculation



Code
# rd04-08-generate-rd04-integrated-figure
if (recompute) {
  publication_root &lt;- normalizePath(getwd(), winslash = "/")
  paths_common &lt;- publication_paths(publication_root)

  # Reuse the inference functions defined above.

  suppressPackageStartupMessages({
    library(dplyr)
    library(ggplot2)
    library(glmmTMB)
    library(patchwork)
    library(readr)
  })
  paths &lt;- publication_fuel_paths(publication_root)
  models_dir &lt;- file.path(publication_root, "outputs", "fuel", "models")
  figures_dir &lt;- file.path(paths$output, "figures")
  tables_dir &lt;- file.path(paths$output, "tables")
  dir.create(figures_dir, recursive = TRUE, showWarnings = FALSE)
  dir.create(tables_dir, recursive = TRUE, showWarnings = FALSE)
  dir.create(paths$manifests, recursive = TRUE, showWarnings = FALSE)

  spec &lt;- rd04_spec
  phase_estimates &lt;- list()
  for (i in seq_len(nrow(spec))) {
    item &lt;- spec[i, ]
    model &lt;- read_saved_model(
      file.path(models_dir, paste0(item$model_id, ".rds")),
      "F01"
    )
    phase_arg &lt;- if (is.na(item$phase)) NULL else item$phase
    s &lt;- integration_setup(model, reference_grid(model, phase_arg))
    # Each treatment/phase mean must average the four study-site contexts.
    stopifnot(all(rowSums(s$avg$A &gt; 0) == 4L))
    phase_estimates[[i]] &lt;- summarize_integrated(
      s,
      item$component,
      item$model_id,
      phase_arg
    )
    if (item$component == "Woody vegetation") {
      # Reuse this same fit for the change: no independent pre/post errors or
      # separately fitted difference model enter the displayed contrast.
      difference_component &lt;- summarize_integrated(
        woody_change_setup(s),
        "Woody vegetation difference (pre-PCT minus post-PCT)",
        item$model_id,
        difference = TRUE
      )
    }
  }
  estimates &lt;- bind_rows(bind_rows(phase_estimates), difference_component) |&gt;
    mutate(
      treatment = factor(treatment, levels = c("gs", "ld", "ha", "hd")),
      phase = factor(
        phase,
        levels = c("Pre-PCT", "Post-PCT", "Vegetation difference")
      ),
      component = factor(
        component,
        levels = c(
          "1-hour fuel",
          "10-hour fuel",
          "100-hour fuel",
          "1,000-hour fuel",
          "Woody vegetation",
          "Herbaceous vegetation",
          "Litter (pre-PCT only)",
          "Duff (pre-PCT only)",
          "Woody vegetation difference (pre-PCT minus post-PCT)"
        )
      )
    ) |&gt;
    arrange(component, phase, treatment)
  stopifnot(
    nrow(estimates) == 60L,
    all(is.finite(estimates$estimate)),
    all(is.finite(estimates$se)),
    all(estimates$se &gt;= 0),
    all(estimates$lcl &lt;= estimates$estimate),
    all(estimates$ucl &gt;= estimates$estimate)
  )
  # Every displayed woody change must equal the plotted pre-minus-post means.
  woody_means &lt;- filter(estimates, component == "Woody vegetation")
  for (trt in levels(estimates$treatment)) {
    pre &lt;- filter(woody_means, treatment == trt, phase == "Pre-PCT")$estimate
    post &lt;- filter(woody_means, treatment == trt, phase == "Post-PCT")$estimate
    delta &lt;- filter(difference_component, treatment == trt)$estimate
    stopifnot(abs(pre - post - delta) &lt; 1e-8)
  }
  write_csv(estimates, file.path(tables_dir, "rd04-fuel-model-estimates.csv"))
}

publication_table(read.csv("outputs/fuel/tables/rd04-fuel-model-estimates.csv"))

Fitting and residual-check functions
To compare candidates fairly, we’ll define fit_and_diagnose() to give each one the same fitting record and residual checks. When called, it reads the candidate’s saved model through read_saved_model() unless refit:true explicitly requests the optimizer and saves a replacement fit. It retains warnings and convergence information and adds simulation-based diagnostics, returning one register row per attempt. Those fields help us distinguish a promising AIC from a fit that still needs work. Sections 03 and 04 call this function during recompute or refit; an ordinary review render reads their saved registers instead.
Small label helpers describe formulas and family objects directly, so each candidate only needs to specify its model components. The optional family_label, ziformula_label, and dispformula_label arguments can still supply display text. In particular, ziGamma() identifies itself as "Gamma" inside its family object, so we keep its explicit label to distinguish that constructor. We also retain the Gaussian and Student-t display names.


Code
# f01-fit-and-diagnose
# Create and return the model and diagnostic output folders.
model_output_paths &lt;- function(paths) {
  models &lt;- file.path(paths$output, "models")
  diagnostics &lt;- file.path(paths$output, "diagnostics")
  dir.create(models, recursive = TRUE, showWarnings = FALSE)
  dir.create(diagnostics, recursive = TRUE, showWarnings = FALSE)
  list(models = models, diagnostics = diagnostics)
}

# Extract test results, retaining errors so other checks can continue.
extract_test &lt;- function(test_fun, simulation) {
  result &lt;- tryCatch(test_fun(simulation), error = function(error) error)
  if (inherits(result, "error")) {
    return(list(
      statistic = NA_real_,
      p_value = NA_real_,
      error = conditionMessage(result)
    ))
  }
  list(
    statistic = unname(result$statistic)[1],
    p_value = result$p.value,
    error = NA_character_
  )
}

# Keep formulas on one line, preserving operators and quoted variable names.
default_formula_label &lt;- function(formula, label = NULL) {
  if (!is.null(label)) return(label)
  paste(trimws(deparse(formula, width.cutoff = 500L)), collapse = " ")
}

# Use family metadata rather than the expression or variable passed by a caller.
default_family_label &lt;- function(family, label = NULL) {
  if (!is.null(label)) return(label)
  paste0(family$family, "(link = ", family$link, ")")
}

fit_and_diagnose &lt;- function(
  model_id,
  response,
  analysis,
  data,
  formula,
  family,
  ziformula,
  dispformula,
  paths,
  simulation_n,
  simulation_seed,
  family_label = NULL,
  ziformula_label = NULL,
  dispformula_label = NULL
) {
  output_paths &lt;- model_output_paths(paths)
  warnings &lt;- character()
  fit &lt;- if (isTRUE(params$refit)) {
    tryCatch(
      withCallingHandlers(
        glmmTMB::glmmTMB(
          formula = formula,
          data = data,
          family = family,
          ziformula = ziformula,
          dispformula = dispformula
        ),
        warning = function(warning) {
          warnings &lt;&lt;- c(warnings, conditionMessage(warning))
          invokeRestart("muffleWarning")
        }
      ),
      error = function(error) error
    )
  } else {
    read_saved_model(
      file.path(output_paths$models, paste0(model_id, ".rds")),
      "F01"
    )
  }

  # Fitting warnings are saved evidence; refreshing residuals must retain them.
  if (!isTRUE(params$refit)) {
    saved_register &lt;- read.csv(file.path(
      paths$manifests,
      "model-comparison.csv"
    ))
    warnings &lt;- stats::na.omit(saved_register$warnings[
      saved_register$model_id == model_id
    ])
  }

  base_record &lt;- tibble::tibble(
    model_id = model_id,
    response = response,
    analysis = analysis,
    n = nrow(data),
    fixed_and_random_formula = default_formula_label(formula),
    family = default_family_label(family, family_label),
    ziformula = default_formula_label(ziformula, ziformula_label),
    dispformula = default_formula_label(dispformula, dispformula_label),
    fit_status = if (inherits(fit, "error")) "error" else "fit",
    fit_message = if (inherits(fit, "error")) {
      conditionMessage(fit)
    } else {
      NA_character_
    },
    warnings = if (length(warnings)) {
      paste(unique(warnings), collapse = " | ")
    } else {
      NA_character_
    },
    pd_hessian = NA,
    aic = NA_real_,
    dharma_uniformity_p = NA_real_,
    dharma_dispersion_p = NA_real_,
    dharma_outlier_p = NA_real_,
    dharma_zero_inflation_p = NA_real_,
    diagnostic_message = NA_character_
  )

  if (inherits(fit, "error")) {
    return(base_record)
  }

  if (isTRUE(params$refit)) {
    saveRDS(fit, file.path(output_paths$models, paste0(model_id, ".rds")))
  }
  simulation &lt;- tryCatch(
    publication_simulate_residuals(
      fit,
      n = simulation_n,
      seed = simulation_seed
    ),
    error = function(error) error
  )
  if (inherits(simulation, "error")) {
    return(dplyr::mutate(
      base_record,
      pd_hessian = fit$sdr$pdHess,
      aic = stats::AIC(fit),
      diagnostic_message = conditionMessage(simulation)
    ))
  }

  # Some DHARMa tests may draw internally. Use a null device so these
  # exploratory diagnostics never create an incidental Rplots.pdf in analysis/.
  grDevices::pdf(file = NULL)
  on.exit(grDevices::dev.off(), add = TRUE)
  uniformity &lt;- extract_test(DHARMa::testUniformity, simulation)
  dispersion &lt;- extract_test(DHARMa::testDispersion, simulation)
  outliers &lt;- extract_test(DHARMa::testOutliers, simulation)
  zero_inflation &lt;- extract_test(DHARMa::testZeroInflation, simulation)

  png(
    filename = file.path(
      output_paths$diagnostics,
      paste0(model_id, "-dharma.png")
    ),
    width = 1800,
    height = 900,
    res = 150
  )
  plot(simulation)
  dev.off()

  dplyr::mutate(
    base_record,
    pd_hessian = fit$sdr$pdHess,
    aic = stats::AIC(fit),
    dharma_uniformity_p = uniformity$p_value,
    dharma_dispersion_p = dispersion$p_value,
    dharma_outlier_p = outliers$p_value,
    dharma_zero_inflation_p = zero_inflation$p_value,
    diagnostic_message = paste(
      stats::na.omit(c(
        uniformity$error,
        dispersion$error,
        outliers$error,
        zero_inflation$error
      )),
      collapse = " | "
    )
  )
}
